insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status) select u.id, 4, 500, 'ADVANCED', 'text', null, $j${"k":"text","text":"Mia: May I help you?\nLily: Yes, please. How much are these socks?\nMia: They're two thousand won. They're on sale today.\nLily: Great! And how much are these shoes?\nMia: They're fifty thousand won.\nLily: Oh, that's expensive. I'll look at the socks again. Thank you.","ko":"미아: 도와 드릴까요? 릴리: 네, 부탁해요. 이 양말은 얼마예요? 미아: 2,000원이에요. 오늘 할인 중이에요. 릴리: 좋아요! 그럼 이 신발은요? 미아: 50,000원이에요. 릴리: 비싸네요. 양말을 다시 볼게요. 고마워요.","test":true}$j$::jsonb, 'approved' from units u join books b on b.id=u.book_id where b.title='비상교육 초5 영어' and u.no=9;
