insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status) select u.id, 7, 9, 'ADVANCED', 'text', null, $j${"k":"text","text":"Wei wants a hat and shoes. The hat is ten thousand won. The shoes are fifty thousand won.\nWei says, \"These shoes are expensive, but they're nice.\"\nHis friend says, \"Look at this hat. It's cheaper.\"\nWei thinks for a moment. \"OK. This hat is better for me today.\"","ko":"웨이는 모자와 신발을 원해. 모자는 10,000원, 신발은 50,000원이야. 웨이는 \"이 신발은 비싸지만 멋져.\"라고 해. 친구가 \"이 모자를 봐. 더 싸.\"라고 해. 웨이는 잠깐 생각하고 \"좋아. 오늘은 이 모자가 더 좋아.\"라고 해.","test":true}$j$::jsonb, 'approved' from units u join books b on b.id=u.book_id where b.title='비상교육 초5 영어' and u.no=9;
